CREATE TABLE IF NOT EXISTS mag_suite_objects(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',parent_id TEXT,owner_user_id TEXT NOT NULL DEFAULT '',content_json TEXT NOT NULL DEFAULT '{}',permissions_json TEXT NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_suite_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,calendar_id TEXT NOT NULL DEFAULT 'primary',title TEXT NOT NULL,start_at INTEGER,end_at INTEGER,attendees_json TEXT NOT NULL DEFAULT '[]',meeting_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_suite_forms(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,title TEXT NOT NULL,fields_json TEXT NOT NULL DEFAULT '[]',settings_json TEXT NOT NULL DEFAULT '{}',active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_suite_form_responses(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,form_id TEXT NOT NULL,response_json TEXT NOT NULL DEFAULT '{}',submitted_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_suite_automations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,trigger_json TEXT NOT NULL DEFAULT '{}',conditions_json TEXT NOT NULL DEFAULT '[]',actions_json TEXT NOT NULL DEFAULT '[]',enabled INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_suite_audit(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT NOT NULL DEFAULT '',action TEXT NOT NULL,object_id TEXT NOT NULL DEFAULT '',detail_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_mag_suite_objects_tenant_kind ON mag_suite_objects(tenant_id,kind,updated_at);
CREATE INDEX IF NOT EXISTS idx_mag_suite_events_tenant ON mag_suite_events(tenant_id,start_at);
